FUNCTION_BLOCK FB_DrillingRig_StickSlipWOB
(*
===================================================================================================
  CYBER-PHYSICAL SYSTEM: ULTRA-DEEP BOREHOLE TOP DRIVE & DRAWWORKS DRILLSTRING CONTROLLER
  SUBSYSTEM: TORSIONAL STICK-SLIP OSCILLATION DAMPING (SOFT-TORQUE) & ACTIVE WOB DECOUPLING
  ARCHITECT: Principal Automation Fellow & Cyber-Physical Systems Chair
  STANDARD:  IEC 61131-3 3rd Ed. / IEC 61508 SIL-3 Dual-Path Interlock Compliant
  EXECUTION: 10.0 ms Real-Time Synchronous Motion Loop (Delta_T = 0.010 s)
===================================================================================================
  MATHEMATICAL FORMULATION & DYNAMICS:
  1. Drillstring Continuous Torsional Wave Equation:
     J_p * rho * d^2(theta)/dt^2 - G * J_p * d^2(theta)/dz^2 + c_damp * d(theta)/dt = 0
     Propagation velocity: c = sqrt(G / rho) ~= 3200 m/s in standard drill pipe steel.
     Phase transit delay: tau = 2 * Depth / c (round-trip transit time).
     Fundamental torsional natural frequency: f_torsion = c / (4 * Depth) [Hz].

  2. Lumped 2-DOF Cyber-Physical State-Space Formulation:
     Let State Vector x = [x1, x2, x3, x4]^T:
       x1 = delta_theta = (theta_td - theta_bit) : Torsional relative twist strain [rad]
       x2 = omega_td                             : Surface top drive rotational velocity [rad/s]
       x3 = omega_bit                            : Downhole roller-cone / PDC bit velocity [rad/s]
       x4 = tau_drillstring                      : Dynamic torsional internal torque [kNm]

     State Equations:
       dx1/dt = x2 - x3
       dx2/dt = (Tau_motor - K_t * x1 - D_t * (x2 - x3) - C_surf * x2) / J_td
       dx3/dt = (K_t * x1 + D_t * (x2 - x3) - Tau_rock_bit(x3, WOB)) / J_bit
       dx4/dt = K_t * (x2 - x3)

  3. Non-Linear Friction Law (Stribeck / Karnopp Stick-Slip Model):
       Tau_rock_bit(omega_bit, WOB) = WOB * R_bit * mu_app(omega_bit)
       mu_app(omega) = mu_coulomb + (mu_static - mu_coulomb) * exp(-(omega/v_stribeck)^2) + alpha_v * omega

  4. Discrete Model Predictive Control (MPC) and Active Impedance Matching:
     Synthesizes rotary speed command modulation:
       Delta_RPM = -K_soft * (Tau_meas - Filtered_Torque) - K_obs * (Omega_td_est - Omega_bit_est)
     Dynamic decoupling with Weight-on-Bit via Drawworks active brake / servo motor.
===================================================================================================
*)

VAR_INPUT
    bEnableSystem               : BOOL;     (* Rig Master Controller Enable Interlock [TRUE=Active] *)
    bHardwireSafetyOK           : BOOL;     (* SIL-3 Crown-O-Matic & Rig Floor Safety Loop Status *)
    bAcknowledgeFaults          : BOOL;     (* Operator Manual Fault Reset & Alarm Cleared Pulse *)
    rTopDriveRPM_Setpoint       : REAL;     (* Driller Surface Rotary Speed Setpoint [rpm] (0.0 .. 250.0) *)
    rTopDriveRPM_Sensor_Ch1     : REAL;     (* Rotary Speed EnDat/Incremental Pulse Encoder 1 [rpm] *)
    rTopDriveRPM_Sensor_Ch2     : REAL;     (* Rotary Speed Magnetic Tachometer Redundant 2 [rpm] *)
    rTopDriveRPM_Sensor_Ch3     : REAL;     (* Rotary Speed VFD Regenerative Flux Estimator 3 [rpm] *)
    rTopDriveTorque_kNm         : REAL;     (* Electromagnetic Air-Gap Reactive Drive Torque [kNm] *)
    rHookLoad_kN                : REAL;     (* Dead-line Anchor Hook Load Cell Telemetry [kN] *)
    rStandpipePressure_bar      : REAL;     (* Mud Pulse Circulation Standpipe Pressure (SPP) [bar] *)
    rTargetWOB_kN               : REAL;     (* Target Weight-on-Bit Recipe Command [kN] (0.0 .. 450.0) *)
    rTargetROP_mph              : REAL;     (* Target Drilling Rate of Penetration [m/h] (0.0 .. 80.0) *)
    rMeasuredBoreholeDepth_m    : REAL;     (* Rig Total Measured Borehole Depth (MD) [m] *)
    rTotalStringWeightInMud_kN  : REAL;     (* Tare Buoyant Drillstring Static Weight [kN] *)
    bDrillstringOffBottom       : BOOL;     (* Geosteering Flag: Drill Bit Suspended Off-Bottom *)
END_VAR

VAR_OUTPUT
    bSystemReady                : BOOL;     (* Automation Ready & Synchronized Status Signal *)
    bStickSlipMitigationActive  : BOOL;     (* Soft-Torque Impedance Damping Loop Closed & Running *)
    bAntiStallActive            : BOOL;     (* Critical Bit Stagnation Fast WOB Relief Triggered *)
    rTopDriveSpeedCmd_rpm       : REAL;     (* Dynamic Compensated Variable Frequency Drive Command [rpm] *)
    rTopDriveTorqueLimit_kNm    : REAL;     (* Dynamic Electric Torque Envelope Limit Command [kNm] *)
    rDrawworksHeaveWOB_Cmd_kN   : REAL;     (* Active Compensated Drawworks Net WOB Tension Command [kN] *)
    rActualCalculatedWOB_kN     : REAL;     (* Real-Time Inertially Compensated Weight-on-Bit [kN] *)
    rEstimatedDownholeBitRPM    : REAL;     (* High-Order Luenberger Observer Downhole Bit Speed [rpm] *)
    rStickSlipSeverityIndex     : REAL;     (* Dimensionless Torsional Oscillation Severity Ratio (0.0..2.5) *)
    rTorsionalEnergyJoules      : REAL;     (* Instantaneous Elastic Strain Energy Stored in Pipe [J] *)
    wControllerStatusWord       : WORD;     (* Diagnostic Bitmask for Supervisory SCADA Telemetry *)
    wSensorHealthMask           : WORD;     (* Diagnostic Channel Status for Redundant Sensor Channels *)
    bCriticalRigAlarm           : BOOL;     (* Emergency Controller Trip & Dynamic Braking Request *)
END_VAR

VAR
    (* --- 2oo3 Triple Modular Redundancy (TMR) Speed Voting Engine --- *)
    rVotedSurfaceRPM            : REAL;     (* Robust Voted Surface Rotary Velocity [rpm] *)
    bCh1_Healthy                : BOOL;     (* Channel 1 Statistical Discrepancy Flag *)
    bCh2_Healthy                : BOOL;     (* Channel 2 Statistical Discrepancy Flag *)
    bCh3_Healthy                : BOOL;     (* Channel 3 Statistical Discrepancy Flag *)
    rTMR_DeltaThreshold_rpm     : REAL := 4.5; (* Inter-channel maximum tolerance deviation [rpm] *)
    iTMR_FaultCounter           : INT  := 0;

    (* --- State-Space Luenberger Observer Variables (Discretized at Ts = 10ms) --- *)
    rState_ThetaTwist_rad       : REAL := 0.0; (* x1: Estimated Pipe Torsional Displacement [rad] *)
    rState_OmegaTD_rads         : REAL := 0.0; (* x2: Filtered Top Drive Speed [rad/s] *)
    rState_OmegaBit_rads        : REAL := 0.0; (* x3: Downhole Bit Angular Velocity [rad/s] *)
    rState_InternalTorque_kNm   : REAL := 0.0; (* x4: Internal Dynamic Torsional Load [kNm] *)

    (* Cyber-Physical Physical Drillstring Continuous Parameters *)
    rEffectiveShearModulus_GPa  : REAL := 79.3;  (* High-Strength Steel G [GPa] *)
    rDrillPipeOuterDiam_m       : REAL := 0.127; (* Standard 5-inch Drill Pipe OD [m] *)
    rDrillPipeInnerDiam_m       : REAL := 0.108; (* Standard 5-inch Drill Pipe ID [m] *)
    rSteelDensity_kgm3          : REAL := 7850.0;(* Steel Density [kg/m^3] *)
    rPolarInertia_Jp            : REAL;          (* Calculated Polar Moment of Area [m^4] *)
    rTorsionalStiffness_Kt      : REAL;          (* Dynamic Depth-Dependent Stiffness [kNm/rad] *)
    rTorsionalDamping_Dt        : REAL;          (* Structural Damping Coefficient [kNm*s/rad] *)
    rTopDriveInertia_Jtd        : REAL := 1250.0;(* Top Drive Motor + Swivel + Saver Sub Inertia [kg*m^2] *)
    rBHA_Inertia_Jbit           : REAL := 480.0; (* Heavy Drill Collars + MWD + Bit Inertia [kg*m^2] *)

    (* Observer Feedback Matrix Gains (Pole-Placed via Ackermann Formulation) *)
    rObsGain_L1                 : REAL := 1.250;
    rObsGain_L2                 : REAL := 4.820;
    rObsGain_L3                 : REAL := 6.140;
    rObsGain_L4                 : REAL := 18.50;

    (* --- Soft-Torque Impedance Matching & Torsional Damping Control Variables --- *)
    rTorqueMean_LPF_kNm         : REAL := 0.0; (* Low-Pass Filtered Baseline Drilling Torque [kNm] *)
    rTorqueFluctuation_kNm      : REAL := 0.0; (* High-Frequency AC Dynamic Torsional Ripple [kNm] *)
    rCharacteristicImpedance    : REAL;        (* Wave Impedance Z_0 = sqrt(J * K) [kNm / (rad/s)] *)
    rDampingGain_Kdamp          : REAL := 0.85;(* Dynamic Tuned Damping Factor *)
    rTorsionalPhaseCorrection   : REAL := 0.0; (* Phase-lead advance compensation term *)
    rSpeedDampingOffset_rpm     : REAL := 0.0; (* Output velocity modifier to absorb reflection *)

    (* --- Weight-on-Bit (WOB) Active Decoupler & Anti-Stall Controller --- *)
    rRawWOB_kN                  : REAL := 0.0;
    rFilteredWOB_kN             : REAL := 0.0;
    rDeltaWOB_kN                : REAL := 0.0;
    rWOB_IntegralError          : REAL := 0.0;
    rWOB_Kp                     : REAL := 0.65;
    rWOB_Ki                     : REAL := 0.08;
    rWOB_Kd                     : REAL := 0.02;
    rPreviousWOB_Error          : REAL := 0.0;
    rAntiStallBackoffFactor     : REAL := 0.0;

    (* --- Stick-Slip Severity & Energy Analysis Accumulators --- *)
    rBitRPM_Peak_Window         : REAL := 0.0;
    rBitRPM_Valley_Window       : REAL := 250.0;
    rWindowTimer_s              : REAL := 0.0;
    rWindowDuration_s           : REAL := 4.0;
    rStickSlipRatio             : REAL := 0.0;

    (* --- Internal Timers and Digital Filters --- *)
    tSamplingTime_s             : REAL := 0.010; (* Loop execution delta [s] *)
    rTorqueFilterCoeff          : REAL := 0.05;  (* Digital RC filter alpha *)
    rWOB_FilterCoeff            : REAL := 0.08;  (* Digital RC filter alpha *)

    (* Finite State Machine Sequencing *)
    iRigOperationalState        : INT  := 0;
    iPreviousRigState           : INT  := 0;
    tStateTimer                 : TON;
    tAntiStallTimer             : TON;
    bStallDetected              : BOOL := FALSE;
    bDegradedSensorMode         : BOOL := FALSE;

    (* Constants *)
    PI                          : REAL := 3.141592653589793;
    RPM_TO_RADS                 : REAL := 0.10471975511965977; (* (2 * PI) / 60.0 *)
    RADS_TO_RPM                 : REAL := 9.54929658551372;    (* 60.0 / (2 * PI) *)
END_VAR

(*
===================================================================================================
                                      CYCLIC LOGIC EXECUTION
===================================================================================================
*)

(* ------------------------------------------------------------------------------------------------
   PHASE 0: EMERGENCY STOP & DETERMINISTIC SAFETY HARD-LOCK INTERLOCK
   ------------------------------------------------------------------------------------------------ *)
IF NOT bHardwireSafetyOK THEN
    bSystemReady               := FALSE;
    bStickSlipMitigationActive := FALSE;
    bAntiStallActive           := FALSE;
    rTopDriveSpeedCmd_rpm      := 0.0;
    rTopDriveTorqueLimit_kNm   := 0.0;
    rDrawworksHeaveWOB_Cmd_kN  := 0.0;
    bCriticalRigAlarm          := TRUE;
    wControllerStatusWord      := 16#F001; (* Safety Trip Active *)
    iRigOperationalState       := 99;      (* Critical Lockout State *)
    RETURN;
END_IF;

(* ------------------------------------------------------------------------------------------------
   PHASE 1: TRIPLE MODULAR REDUNDANCY (2oo3) SPEED SENSOR VOTING ALGORITHM
   ------------------------------------------------------------------------------------------------ *)
(* Compute cross-channel differential residuals *)
bCh1_Healthy := (ABS(rTopDriveRPM_Sensor_Ch1 - rTopDriveRPM_Sensor_Ch2) <= rTMR_DeltaThreshold_rpm) OR
                (ABS(rTopDriveRPM_Sensor_Ch1 - rTopDriveRPM_Sensor_Ch3) <= rTMR_DeltaThreshold_rpm);

bCh2_Healthy := (ABS(rTopDriveRPM_Sensor_Ch2 - rTopDriveRPM_Sensor_Ch1) <= rTMR_DeltaThreshold_rpm) OR
                (ABS(rTopDriveRPM_Sensor_Ch2 - rTopDriveRPM_Sensor_Ch3) <= rTMR_DeltaThreshold_rpm);

bCh3_Healthy := (ABS(rTopDriveRPM_Sensor_Ch3 - rTopDriveRPM_Sensor_Ch1) <= rTMR_DeltaThreshold_rpm) OR
                (ABS(rTopDriveRPM_Sensor_Ch3 - rTopDriveRPM_Sensor_Ch2) <= rTMR_DeltaThreshold_rpm);

(* Synthesize Sensor Health Diagnostics Bitmask *)
wSensorHealthMask := 16#0000;
IF bCh1_Healthy THEN wSensorHealthMask := wSensorHealthMask OR 16#0001; END_IF;
IF bCh2_Healthy THEN wSensorHealthMask := wSensorHealthMask OR 16#0002; END_IF;
IF bCh3_Healthy THEN wSensorHealthMask := wSensorHealthMask OR 16#0004; END_IF;

(* 2oo3 Median Voting Synthesis with Graceful Dynamic Degradation *)
IF bCh1_Healthy AND bCh2_Healthy AND bCh3_Healthy THEN
    (* Full TMR Healthy: Select Exact Mathematical Median *)
    IF (rTopDriveRPM_Sensor_Ch1 >= rTopDriveRPM_Sensor_Ch2 AND rTopDriveRPM_Sensor_Ch1 <= rTopDriveRPM_Sensor_Ch3) OR
       (rTopDriveRPM_Sensor_Ch1 <= rTopDriveRPM_Sensor_Ch2 AND rTopDriveRPM_Sensor_Ch1 >= rTopDriveRPM_Sensor_Ch3) THEN
        rVotedSurfaceRPM := rTopDriveRPM_Sensor_Ch1;
    ELSIF (rTopDriveRPM_Sensor_Ch2 >= rTopDriveRPM_Sensor_Ch1 AND rTopDriveRPM_Sensor_Ch2 <= rTopDriveRPM_Sensor_Ch3) OR
          (rTopDriveRPM_Sensor_Ch2 <= rTopDriveRPM_Sensor_Ch1 AND rTopDriveRPM_Sensor_Ch2 >= rTopDriveRPM_Sensor_Ch3) THEN
        rVotedSurfaceRPM := rTopDriveRPM_Sensor_Ch2;
    ELSE
        rVotedSurfaceRPM := rTopDriveRPM_Sensor_Ch3;
    END_IF;
    bDegradedSensorMode := FALSE;
ELSIF bCh1_Healthy AND bCh2_Healthy THEN
    (* Dual Redundant Degraded Mode *)
    rVotedSurfaceRPM := (rTopDriveRPM_Sensor_Ch1 + rTopDriveRPM_Sensor_Ch2) * 0.5;
    bDegradedSensorMode := TRUE;
ELSIF bCh1_Healthy AND bCh3_Healthy THEN
    rVotedSurfaceRPM := (rTopDriveRPM_Sensor_Ch1 + rTopDriveRPM_Sensor_Ch3) * 0.5;
    bDegradedSensorMode := TRUE;
ELSIF bCh2_Healthy AND bCh3_Healthy THEN
    rVotedSurfaceRPM := (rTopDriveRPM_Sensor_Ch2 + rTopDriveRPM_Sensor_Ch3) * 0.5;
    bDegradedSensorMode := TRUE;
ELSE
    (* Total TMR Sensor Collapse: Single Sensor Fallback or Lockout *)
    IF bCh1_Healthy THEN
        rVotedSurfaceRPM := rTopDriveRPM_Sensor_Ch1;
    ELSIF bCh2_Healthy THEN
        rVotedSurfaceRPM := rTopDriveRPM_Sensor_Ch2;
    ELSIF bCh3_Healthy THEN
        rVotedSurfaceRPM := rTopDriveRPM_Sensor_Ch3;
    ELSE
        bCriticalRigAlarm := TRUE;
        wControllerStatusWord := 16#F002; (* TMR All Sensor Loss *)
        iRigOperationalState := 99;
        RETURN;
    END_IF;
    bDegradedSensorMode := TRUE;
END_IF;

(* ------------------------------------------------------------------------------------------------
   PHASE 2: RIG GEOMETRIC & CYBER-PHYSICAL DRILLSTRING PARAMETER UPDATE
   ------------------------------------------------------------------------------------------------ *)
(* Polar second moment of area: J_p = (PI / 32) * (OD^4 - ID^4) *)
rPolarInertia_Jp := (PI / 32.0) * (EXPT(rDrillPipeOuterDiam_m, 4) - EXPT(rDrillPipeInnerDiam_m, 4));

(* Total Torsional Rig Stiffness: K_t = (G * J_p) / Length (with safe lower bound) *)
IF rMeasuredBoreholeDepth_m > 50.0 THEN
    rTorsionalStiffness_Kt := ((rEffectiveShearModulus_GPa * 1.0E6) * rPolarInertia_Jp) / rMeasuredBoreholeDepth_m;
ELSE
    rTorsionalStiffness_Kt := ((rEffectiveShearModulus_GPa * 1.0E6) * rPolarInertia_Jp) / 50.0;
END_IF;

(* Structural Material Damping coefficient estimated proportional to modal damping *)
rTorsionalDamping_Dt := 2.0 * 0.04 * SQRT(rTorsionalStiffness_Kt * rBHA_Inertia_Jbit);

(* Characteristic Acoustic Impedance Z_0 = sqrt(K_t * J_pipe_total) *)
rCharacteristicImpedance := SQRT(rTorsionalStiffness_Kt * (rBHA_Inertia_Jbit + rTopDriveInertia_Jtd * 0.3));

(* ------------------------------------------------------------------------------------------------
   PHASE 3: HIGH-ORDER CYBER-PHYSICAL LUENBERGER DOWNHOLE OBSERVER
   ------------------------------------------------------------------------------------------------ *)
(* Observer Innovation Prediction vs Measurement *)
rTorqueMean_LPF_kNm := rTorqueMean_LPF_kNm + rTorqueFilterCoeff * (rTopDriveTorque_kNm - rTorqueMean_LPF_kNm);
rTorqueFluctuation_kNm := rTopDriveTorque_kNm - rTorqueMean_LPF_kNm;

(* Innovation term on surface angular velocity *)
VAR_TEMP
    rSurfaceVel_rads        : REAL;
    rInnovation_Vel         : REAL;
    rEstTorque_kNm          : REAL;
    rRockReactionTorque_est : REAL;
END_VAR;

rSurfaceVel_rads := rVotedSurfaceRPM * RPM_TO_RADS;
rInnovation_Vel  := rSurfaceVel_rads - rState_OmegaTD_rads;

(* Downhole rock-bit friction estimated via Coulomb-Stribeck approximation *)
rRockReactionTorque_est := (rFilteredWOB_kN * 0.08) * (0.45 / (1.0 + ABS(rState_OmegaBit_rads) * 0.25) + 0.15);

(* Continuous-to-Discrete Forward Euler Integration of Observer States *)
rState_ThetaTwist_rad := rState_ThetaTwist_rad + tSamplingTime_s * (
    (rState_OmegaTD_rads - rState_OmegaBit_rads) + rObsGain_L1 * rInnovation_Vel
);

rEstTorque_kNm := (rTorsionalStiffness_Kt * rState_ThetaTwist_rad) / 1000.0;

rState_OmegaTD_rads := rState_OmegaTD_rads + tSamplingTime_s * (
    ((rTopDriveTorque_kNm - rEstTorque_kNm - rTorsionalDamping_Dt * (rState_OmegaTD_rads - rState_OmegaBit_rads)) / (rTopDriveInertia_Jtd / 1000.0))
    + rObsGain_L2 * rInnovation_Vel
);

rState_OmegaBit_rads := rState_OmegaBit_rads + tSamplingTime_s * (
    ((rEstTorque_kNm - rRockReactionTorque_est + rTorsionalDamping_Dt * (rState_OmegaTD_rads - rState_OmegaBit_rads)) / (rBHA_Inertia_Jbit / 1000.0))
    + rObsGain_L3 * rInnovation_Vel
);

(* Guard against non-physical negative bit rotation during standard rotary drilling *)
IF rState_OmegaBit_rads < -5.0 THEN
    rState_OmegaBit_rads := -5.0;
END_IF;

rEstimatedDownholeBitRPM := rState_OmegaBit_rads * RADS_TO_RPM;

(* Elastic Torsional Potential Energy: E = 0.5 * K_t * theta^2 *)
rTorsionalEnergyJoules := 0.5 * (rTorsionalStiffness_Kt * 1000.0) * EXPT(rState_ThetaTwist_rad, 2);

(* ------------------------------------------------------------------------------------------------
   PHASE 4: REAL-TIME STICK-SLIP SEVERITY ESTIMATION
   ------------------------------------------------------------------------------------------------ *)
(* Sliding window peak-to-peak downhole bit velocity tracking *)
rWindowTimer_s := rWindowTimer_s + tSamplingTime_s;

IF rEstimatedDownholeBitRPM > rBitRPM_Peak_Window THEN
    rBitRPM_Peak_Window := rEstimatedDownholeBitRPM;
END_IF;

IF rEstimatedDownholeBitRPM < rBitRPM_Valley_Window THEN
    rBitRPM_Valley_Window := rEstimatedDownholeBitRPM;
END_IF;

IF rWindowTimer_s >= rWindowDuration_s THEN
    IF rTopDriveRPM_Setpoint > 5.0 THEN
        rStickSlipSeverityIndex := (rBitRPM_Peak_Window - rBitRPM_Valley_Window) / (2.0 * rTopDriveRPM_Setpoint);
    ELSE
        rStickSlipSeverityIndex := 0.0;
    END_IF;

    (* Reset peak-valley tracking buffers *)
    rBitRPM_Peak_Window   := rEstimatedDownholeBitRPM;
    rBitRPM_Valley_Window := rEstimatedDownholeBitRPM;
    rWindowTimer_s        := 0.0;
END_IF;

(* ------------------------------------------------------------------------------------------------
   PHASE 5: WEIGHT-ON-BIT (WOB) DYNAMICS & DRAWWORKS COMPENSATION
   ------------------------------------------------------------------------------------------------ *)
(* Calculate actual bit load from hook load balance: WOB = Total Buoyant Weight - Hook Load *)
IF NOT bDrillstringOffBottom THEN
    rRawWOB_kN := rTotalStringWeightInMud_kN - rHookLoad_kN;
    IF rRawWOB_kN < 0.0 THEN
        rRawWOB_kN := 0.0;
    END_IF;
ELSE
    rRawWOB_kN := 0.0;
END_IF;

(* Digital Filtering of WOB to attenuate mud pump fluid pulsation spikes *)
rFilteredWOB_kN := rFilteredWOB_kN + rWOB_FilterCoeff * (rRawWOB_kN - rFilteredWOB_kN);
rActualCalculatedWOB_kN := rFilteredWOB_kN;

(* ------------------------------------------------------------------------------------------------
   PHASE 6: MULTI-STAGE FINITE STATE MACHINE (SUPERVISORY OPERATING MODES)
   ------------------------------------------------------------------------------------------------ *)
CASE iRigOperationalState OF

    0: (* STATE_SYSTEM_INITIALIZE: Calibration and Offset Nulling *)
        bSystemReady               := FALSE;
        bStickSlipMitigationActive := FALSE;
        bAntiStallActive           := FALSE;
        bCriticalRigAlarm          := FALSE;
        rTopDriveSpeedCmd_rpm      := 0.0;
        rTopDriveTorqueLimit_kNm   := 15.0; (* Standby safety limit *)
        rDrawworksHeaveWOB_Cmd_kN  := 0.0;
        wControllerStatusWord      := 16#0001;

        IF bEnableSystem AND (rMeasuredBoreholeDepth_m > 10.0) THEN
            iRigOperationalState := 10;
        END_IF;

    10: (* STATE_STANDBY_READY: Rig Prepared for Drilling Engagement *)
        bSystemReady               := TRUE;
        bStickSlipMitigationActive := FALSE;
        bAntiStallActive           := FALSE;
        rTopDriveSpeedCmd_rpm      := 0.0;
        rTopDriveTorqueLimit_kNm   := 25.0;
        rDrawworksHeaveWOB_Cmd_kN  := 0.0;
        wControllerStatusWord      := 16#0010;

        IF NOT bEnableSystem THEN
            iRigOperationalState := 0;
        ELSIF rTopDriveRPM_Setpoint > 5.0 THEN
            iRigOperationalState := 20;
        END_IF;

    20: (* STATE_ROTARY_DRILLING_NOMINAL: Open-Loop Speed Regulation *)
        bSystemReady               := TRUE;
        bStickSlipMitigationActive := FALSE;
        bAntiStallActive           := FALSE;
        wControllerStatusWord      := 16#0020;

        (* Standard ramp tracking *)
        rTopDriveSpeedCmd_rpm    := rTopDriveRPM_Setpoint;
        rTopDriveTorqueLimit_kNm := 45.0;
        rDrawworksHeaveWOB_Cmd_kN := rTargetWOB_kN;

        (* Transition triggers *)
        IF NOT bEnableSystem THEN
            iRigOperationalState := 10;
        ELSIF rStickSlipSeverityIndex > 0.40 THEN
            iRigOperationalState := 30; (* Escalate to active damping *)
        ELSIF (rEstimatedDownholeBitRPM <= 2.0) AND (rTopDriveRPM_Setpoint > 30.0) THEN
            iRigOperationalState := 40; (* Direct trigger into anti-stall *)
        END_IF;

    30: (* STATE_STICK_SLIP_ACTIVE_DAMPING: Dynamic Wave Impedance Matching (Soft-Torque) *)
        bSystemReady               := TRUE;
        bStickSlipMitigationActive := TRUE;
        bAntiStallActive           := FALSE;
        wControllerStatusWord      := 16#0040;

        (* Soft-Torque Impedance Matching Algorithm:
           Modulate top drive velocity proportionally to dynamic torsional torque ripple.
           This causes top drive to simulate infinite mechanical inertia or characteristic impedance absorption,
           preventing torsional waves from reflecting back down the drillstring *)
        rSpeedDampingOffset_rpm := (rTorqueFluctuation_kNm / (rCharacteristicImpedance * 0.001)) * rDampingGain_Kdamp;

        (* Saturate speed damping modifier within safe dynamic limits (+/- 35% of setpoint) *)
        IF rSpeedDampingOffset_rpm > (rTopDriveRPM_Setpoint * 0.35) THEN
            rSpeedDampingOffset_rpm := (rTopDriveRPM_Setpoint * 0.35);
        ELSIF rSpeedDampingOffset_rpm < -(rTopDriveRPM_Setpoint * 0.35) THEN
            rSpeedDampingOffset_rpm := -(rTopDriveRPM_Setpoint * 0.35);
        END_IF;

        (* Apply commanded speed with absorbing phase adjustment *)
        rTopDriveSpeedCmd_rpm    := rTopDriveRPM_Setpoint - rSpeedDampingOffset_rpm;
        rTopDriveTorqueLimit_kNm := 65.0;

        (* Coordinated WOB PID Regulation with Differential Standpipe Pressure Feedforward *)
        rDeltaWOB_kN := rTargetWOB_kN - rFilteredWOB_kN;
        rWOB_IntegralError := rWOB_IntegralError + rDeltaWOB_kN * tSamplingTime_s;

        (* Clamp Anti-Windup *)
        IF rWOB_IntegralError > 100.0 THEN rWOB_IntegralError := 100.0; END_IF;
        IF rWOB_IntegralError < -100.0 THEN rWOB_IntegralError := -100.0; END_IF;

        rDrawworksHeaveWOB_Cmd_kN := rTargetWOB_kN + (rWOB_Kp * rDeltaWOB_kN) + (rWOB_Ki * rWOB_IntegralError);

        (* Check Transitions *)
        IF NOT bEnableSystem THEN
            iRigOperationalState := 10;
        ELSIF (rEstimatedDownholeBitRPM <= 1.0) AND (rTopDriveTorque_kNm > 50.0) THEN
            iRigOperationalState := 40; (* Severe Bit Stall *)
        ELSIF rStickSlipSeverityIndex < 0.20 THEN
            iRigOperationalState := 20; (* Return to nominal *)
        END_IF;

    40: (* STATE_SEVERE_STICK_SLIP_ANTI_STALL: Dynamic Unload & Torque Shock Relief *)
        bSystemReady               := TRUE;
        bStickSlipMitigationActive := TRUE;
        bAntiStallActive           := TRUE;
        wControllerStatusWord      := 16#0080;

        (* Fast Drawworks Active WOB Relief: Reduce WOB by 60% immediately to shed friction *)
        rDrawworksHeaveWOB_Cmd_kN := rTargetWOB_kN * 0.40;

        (* Top Drive Speed Bump to Break Static Friction Lock *)
        rTopDriveSpeedCmd_rpm    := rTopDriveRPM_Setpoint * 1.15;
        rTopDriveTorqueLimit_kNm := 80.0; (* Momentary peak torque budget *)

        tAntiStallTimer(IN := TRUE, PT := T#3S);

        IF tAntiStallTimer.Q OR (rEstimatedDownholeBitRPM > (rTopDriveRPM_Setpoint * 0.60)) THEN
            tAntiStallTimer(IN := FALSE);
            bAntiStallActive := FALSE;
            iRigOperationalState := 30; (* Recover back to active damping *)
        END_IF;

    50: (* STATE_GRACEFUL_DEGRADATION: Sensor Fault Tolerant Open-Loop Controller *)
        bSystemReady               := TRUE;
        bStickSlipMitigationActive := FALSE;
        bAntiStallActive           := FALSE;
        wControllerStatusWord      := 16#0100;

        (* Conservative operating mode: Speed clamped, torque limited *)
        IF rTopDriveRPM_Setpoint > 80.0 THEN
            rTopDriveSpeedCmd_rpm := 80.0;
        ELSE
            rTopDriveSpeedCmd_rpm := rTopDriveRPM_Setpoint;
        END_IF;
        rTopDriveTorqueLimit_kNm  := 40.0;
        rDrawworksHeaveWOB_Cmd_kN := rTargetWOB_kN * 0.75;

        IF bAcknowledgeFaults AND (NOT bDegradedSensorMode) THEN
            iRigOperationalState := 20;
        END_IF;

    99: (* STATE_EMERGENCY_SHUTDOWN_TRIP: Complete Protective Lockout *)
        bSystemReady               := FALSE;
        bStickSlipMitigationActive := FALSE;
        bAntiStallActive           := FALSE;
        bCriticalRigAlarm          := TRUE;
        rTopDriveSpeedCmd_rpm      := 0.0;
        rTopDriveTorqueLimit_kNm   := 0.0;
        rDrawworksHeaveWOB_Cmd_kN  := 0.0;
        wControllerStatusWord      := 16#E000;

        IF bAcknowledgeFaults AND bHardwireSafetyOK THEN
            bCriticalRigAlarm    := FALSE;
            iRigOperationalState := 0;
        END_IF;

    ELSE
        iRigOperationalState := 99;
END_CASE;

(* Sensor Degradation Supervisor Transition *)
IF bDegradedSensorMode AND (iRigOperationalState = 20 OR iRigOperationalState = 30) THEN
    iRigOperationalState := 50;
END_IF;

END_FUNCTION_BLOCK
